function applyProductMaster__legacy_v0(c,identity){const v=productMasters().find(row=>productIdentityCode(row)===identity||productLabel(row)===identity);if(!v){c.product=identity;return}c.productIdentityCode=productIdentityCode(v);c.variety=String(v[1]||'').trim();c.riceType=cleanRiceType(v);c.brokenText=cleanBroken(v);c.broken=num(String(c.brokenText).match(/[\d.]+/)?.[0]||0);c.finish=String(v[17]||'').trim();c.cropYear=currentCropYear();c.standardBasis=/contract specific|buyer specific|customer specific/i.test(String(v[5]||''))?'AS PER SPECIFICATIONS BELOW':'AS PER ORIGIN STANDARD';c.product=[c.variety,c.riceType].filter(Boolean).join(' ');c.additionalQuality=String(v[18]||DEFAULT_QUALITY).trim();c.quality=qualityDescription(c);c.specMode='Contract Specific';const fields=[['Average Grain Length',v[6]],['Moisture',v[8]],['Damaged / Shriveled / Yellow',v[9]],['Chalky / Immature',v[10]],['Contrasting / Other Varieties',v[11]],['Foreign Grains',v[12]],['Foreign Matter',v[13]],['Paddy',v[14]],['Red Kernels / Red Rice',v[15]],['Under-milled / Red-striped',v[16]]];let custom=[];try{custom=JSON.parse(String(v[20]||'[]'))}catch{}c.specRows=[...fields.filter(x=>x[1]).map(([name,value])=>({name,value})),...(Array.isArray(custom)?custom.map(x=>({name:String(x.name||''),value:String(x.limit||'')})).filter(x=>x.name||x.value):[])]}
