function documentsPresented(c){const master=exportDocumentMaster(c),source=Array.isArray(c?.documentsPresented)&&c.documentsPresented.length?c.documentsPresented:(c?.docs?.length?c.docs:defaultDocsFor(c)).map((name,i)=>{const m=master.find(v=>String(v[0]||'')===String(name));return{sequence:i+1,name,original:num(m?.[1]??1),copies:num(m?.[2]??0)}}),wanted=inspectionDocumentName(c?.inspection);const rows=source.filter(row=>!isInspectionDocument(row,c)).map(r=>({name:String(r.name||r.documentName||'').trim(),original:Math.max(0,num(r.original)),copies:Math.max(0,num(r.copies)),...(r.autoSource?{autoSource:r.autoSource}:{})})).filter(r=>r.name);if(wanted)rows.push({name:wanted,original:1,copies:1,autoSource:'inspection'});return rows.map((r,i)=>({...r,sequence:i+1}))}
