function effectiveTerms__legacy_v0(c){const shared=exportMasterTerms(c),out=[...(shared.length?shared:DEFAULT_TERMS),...(c.terms||[])];if(c.incoterm==='FOB')out.push('Load Port Terminal Handling Charges (THC), if applicable, shall be for Buyer’s account.');out.push(`Insurance shall be for ${c.insurance==="Seller's Account"?'Seller’s':'Buyer’s'} account.`);if(c.inspection&&!['None','No'].includes(c.inspection))out.push(`Inspection by ${c.inspection} at Seller’s cost.`);if(String(c.paymentCode).startsWith('LC_'))out.push(...lcSpecificTerms(c));else out.push('Partial shipment allowed.');if(c.seller==='TG')out.push('Third-party documents are acceptable except Commercial Invoice and documents specifically required to be issued by the Seller.');return[...new Set(out.map(x=>String(x).trim()).filter(Boolean))]}
