function parsePackingLines(text,qty,containers,price){const out=[];for(const line of lines(text)){const m=line.match(/(\d+(?:\.\d+)?)\s*(KG|KGS|LB|LBS)\b/i);if(!m||!/BAG|SACK|PACK/i.test(line))continue;const size=num(m[1]),unit=/LB/i.test(m[2])?'LB':'KG',type=/JUTE/i.test(line)?'Jute Bags':/PAPER/i.test(line)?'Paper Bags':'PP Bags',brand=((line.match(/(?:BRAND|MARKING)\s*(?::|-)?\s*([A-Z0-9][A-Z0-9 &._\/-]{0,40}?)(?=\s+(?:TARE|MASTER BAG|CONTAINERS?|CNTRS?|\d+(?:\.\d+)?\s*(?:MT|MTS|M\/TONS?))|$)/i)||[])[1]||'').trim(),tare=firstNumber((line.match(/TARE[^\d]{0,8}(\d+(?:\.\d+)?)/i)||[])[1]),lineContainers=firstNumber((line.match(/(\d+)\s*(?:X\s*)?(?:CONTAINERS?|CNTRS?)/i)||[])[1]),lineQty=firstNumber((line.match(/(\d+(?:\.\d+)?)\s*(?:MT|MTS|M\/TONS?)/i)||[])[1]);if(!out.some(x=>x.size===size&&x.unit===unit&&x.type===type))out.push({type,size,unit,brand,tare,containers:lineContainers,weightPer:lineContainers&&lineQty?lineQty/lineContainers:0,price:num(price),freight:0,insurance:0,extraBagPct:0,masterBag:{enabled:/MASTER BAG/i.test(line),qty:firstNumber((line.match(/MASTER BAG[^\d]{0,12}(\d+)/i)||[])[1]),tare:firstNumber((line.match(/MASTER BAG.*?TARE[^\d]{0,8}(\d+(?:\.\d+)?)/i)||[])[1])}})}if(out.length===1){out[0].containers=out[0].containers||num(containers);out[0].weightPer=out[0].weightPer||(containers?num(qty)/num(containers):0)}if(out.length>1&&out.every(x=>!x.containers)&&containers%out.length===0)for(const x of out)x.containers=containers/out.length;if(containers)for(const x of out)x.weightPer=x.weightPer||qty/containers;return out}
