function openLCUpload(shipId=''){if(!state.shipments.length)return alert('Create or import a contract first.');openModal('Upload L/C',readerBody('lc',shipId),`<button class="btn" data-modal-close>Close</button><button class="btn green" id="readerRun">READ L/C WITH GEMINI</button>`);document.getElementById('readerRun').onclick=async()=>{const progress=document.getElementById('readerProgress'),file=document.getElementById('readerFile').files[0],pasted=document.getElementById('readerText').value.trim();try{progress.textContent='Reading L/C with Gemini…';const x=await readWithGemini('lc',file,pasted,msg=>progress.textContent=msg);progress.textContent='Gemini extraction complete — compare it with the Sales Contract below.';showLCReview(x);decorateLCAIReview(x)}catch(e){progress.textContent=`Gemini reader unavailable: ${e.message}`;if(!confirm(`${e.message}\n\nUse the local document reader instead?`))return;try{const raw=pasted||await readFile(file,msg=>progress.textContent=msg),x=parseLCText(raw);x._readerProvider='Local fallback';x._readerModel='';progress.textContent='Local fallback extraction complete — compare it with the Sales Contract below.';showLCReview(x);decorateLCAIReview(x)}catch(localError){progress.textContent='';alert(localError.message)}}}}
function decorateLCAIReview(x){const section=document.querySelector('#readerReview .section');if(!section)return;section.insertAdjacentHTML('afterbegin',`<div class="metaText">Reader: ${esc(x._readerProvider||'Local')} ${x._readerModel?`· ${esc(x._readerModel)}`:''}</div>${readerNotesHTML(x,'lc')}`);const grid=section.querySelector('.grid3');if(grid){grid.insertAdjacentHTML('beforeend',`<div class="field"><label>L/C Amount Tolerance</label><input id="rlTolerance" value="${esc(x.tolerance||'')}"></div><div class="field"><label>Expiry Place</label><input id="rlExpiryPlace" value="${esc(x.expiryPlace||'')}"></div><div class="field full"><label>Bank Charges</label><textarea id="rlBankCharges">${esc(x.bankCharges||'')}</textarea></div><div class="field full"><label>Insurance Requirement</label><textarea id="rlInsuranceReq">${esc(x.insuranceRequirement||'')}</textarea></div><div class="field full"><label>B/L Instructions</label><textarea id="rlBLInstructions">${esc(x.blInstructions||'')}</textarea></div>`)}const button=document.getElementById('saveLCImport');if(button&&button.onclick){const original=button.onclick;button.onclick=()=>{const shipId=document.getElementById('readerShipment')?.value||'',extra={tolerance:document.getElementById('rlTolerance')?.value.trim()||'',expiryPlace:document.getElementById('rlExpiryPlace')?.value.trim()||'',bankCharges:document.getElementById('rlBankCharges')?.value.trim()||'',insuranceRequirement:document.getElementById('rlInsuranceReq')?.value.trim()||'',blInstructions:document.getElementById('rlBLInstructions')?.value.trim()||'',reader:x._readerProvider||'Local fallback',readerModel:x._readerModel||'',readerNotes:Array.isArray(x.notes)?x.notes:[]};original();const s=state.shipments.find(v=>v.id===shipId);if(s?.lc){Object.assign(s.lc,extra);lotsFor(s).forEach(l=>{if(l.lc)Object.assign(l.lc,structuredClone(extra))});save();window.TT_SHARED_SYNC?.flush?.()}}}}
function lcMovementFields(x){const options=value=>['Allowed','Not Allowed','Review'].map(v=>`<option ${value===v?'selected':''}>${v}</option>`).join('');return`<div class="field"><label>Partial Shipment</label><select id="rlPartial">${options(x.partialShipment)}</select></div><div class="field"><label>Trans-shipment</label><select id="rlTrans">${options(x.transshipment)}</select></div>`}
function lcDiscrepancyHTML(x){const s=state.shipments.find(v=>v.id===document.getElementById('readerShipment')?.value),c=contractByRef(s?.contractRef),issues=[];if(!c)return'<div class="notice red">Select the correct Sales Contract before reviewing this L/C.</div>';const value=(c.packings||[]).reduce((sum,p)=>sum+num(p.containers)*num(p.weightPer)*unitRate(p,c),0),buyer=(customer(c.customerId)?.name||s.buyer||'').toUpperCase();if(x.currency&&c.currency&&x.currency!==c.currency)issues.push(`Currency differs: Contract ${c.currency}; L/C ${x.currency}.`);if(x.amount&&value&&Math.abs(x.amount-value)>.01)issues.push(`Amount differs: Contract ${money(value,c.currency)}; L/C ${money(x.amount,x.currency)}.`);if(x.applicant&&buyer&&!x.applicant.toUpperCase().includes(buyer))issues.push(`Applicant does not match Buyer: ${buyer}.`);if(x.partialShipment==='Not Allowed')issues.push('L/C prohibits partial shipment although the Sales Contract requires it to be allowed.');if(x.transshipment==='Not Allowed')issues.push('L/C prohibits trans-shipment although the Sales Contract requires it to be allowed.');return issues.length?`<div class="notice red"><b>Discrepancies requiring review / amendment</b><br>${issues.map(esc).join('<br>')}</div>`:'<div class="notice">No amount, currency, buyer or shipment-permission conflict was detected in the extracted fields.</div>'}
function showLCReview(x){readerReview.innerHTML=`<div class="section"><h3>Review extracted L/C master</h3>${lcDiscrepancyHTML(x)}<div class="grid3"><div class="field"><label>L/C Number</label><input id="rlNo" value="${esc(x.lcNo)}"></div><div class="field"><label>L/C Date</label><input id="rlDate" type="date" value="${x.lcDate}"></div><div class="field"><label>Applicant</label><input id="rlApplicant" value="${esc(x.applicant)}"></div><div class="field"><label>Beneficiary</label><input id="rlBeneficiary" value="${esc(x.beneficiary)}"></div><div class="field"><label>Issuing Bank</label><input id="rlIssueBank" value="${esc(x.issuingBank)}"></div><div class="field"><label>Advising / Available With</label><input id="rlAdvBank" value="${esc(x.advisingBank)}"></div><div class="field"><label>Currency</label><input id="rlCurrency" value="${x.currency}"></div><div class="field"><label>Amount</label><input id="rlAmount" type="number" value="${x.amount||''}"></div><div class="field"><label>Expiry</label><input id="rlExpiry" type="date" value="${x.expiryDate}"></div><div class="field"><label>Latest Shipment</label><input id="rlLatest" type="date" value="${x.latestShipmentDate}"></div><div class="field"><label>Port of Loading</label><input id="rlPOL" value="${esc(x.pol)}"></div><div class="field"><label>Port of Discharge</label><input id="rlPOD" value="${esc(x.pod)}"></div><div class="field"><label>Presentation Days</label><input id="rlPresentation" type="number" value="${x.presentationPeriod||''}"></div><div class="field"><label>Payment</label><select id="rlPayment"><option value="LC_SIGHT" ${x.paymentCode==='LC_SIGHT'?'selected':''}>L/C at Sight</option><option value="LC_USANCE" ${x.paymentCode==='LC_USANCE'?'selected':''}>Usance L/C</option></select></div><div class="field"><label>Usance Days</label><input id="rlUsance" type="number" value="${x.usanceDays||0}"></div>${lcMovementFields(x)}<div class="field full"><label>Documents Required</label><textarea id="rlDocs">${esc(x.documents.join('\n'))}</textarea></div><div class="field full"><label>Additional Conditions</label><textarea id="rlConditions">${esc(x.conditions.join('\n'))}</textarea></div></div><div class="notice warn">This becomes the shipment L/C master and will update document checklists, payment wording, banks, ports and shipment dates.</div><button class="btn green" id="saveLCImport">SAVE L/C MASTER</button></div>`;saveLCImport.onclick=()=>{const s=state.shipments.find(v=>v.id===readerShipment.value),c=contractByRef(s.contractRef);if(!rlNo.value.trim())return alert('L/C Number is required.');s.lc={saved:true,lcNo:rlNo.value.trim(),lcDate:rlDate.value,applicant:rlApplicant.value.trim(),beneficiary:rlBeneficiary.value.trim(),issuingBank:rlIssueBank.value.trim(),advisingBank:rlAdvBank.value.trim(),currency:rlCurrency.value.trim(),amount:num(rlAmount.value),expiryDate:rlExpiry.value,latestShipmentDate:rlLatest.value,pol:rlPOL.value.trim(),pod:rlPOD.value.trim(),presentationPeriod:num(rlPresentation.value),partialShipment:rlPartial.value,transshipment:rlTrans.value,paymentCode:rlPayment.value,usanceDays:num(rlUsance.value),documents:rlDocs.value.split('\n').filter(Boolean),conditions:rlConditions.value.split('\n').filter(Boolean),sourceText:x.sourceText,importedAt:new Date().toISOString()};c.paymentCode=s.lc.paymentCode;c.usanceDays=s.lc.usanceDays;c.currency=s.lc.currency||c.currency;c.shipmentDate=s.lc.latestShipmentDate||c.shipmentDate;c.pol=s.lc.pol||c.pol;c.podPort=s.lc.pod||c.podPort;if(s.lc.documents.length)c.docs=[...s.lc.documents];s.customs.currency=c.currency;s.covering.bank=s.lc.advisingBank||s.lc.issuingBank;lotsFor(s).forEach(l=>{l.lc=structuredClone(s.lc);l.customs.currency=c.currency;l.covering.bank=s.covering.bank});audit('L/C Master','Uploaded, reviewed and mapped',`${c.ref} · ${s.lc.lcNo}`);closeModal();currentShipmentId=s.id;activeWorkspace='contract';view='shipments';renderShipmentWorkspace()}}

function sellerOf(c){return SELLER_DETAILS[c.seller]||SELLER_DETAILS.TTI}
function buyerOf(c){if(c?._documentBuyer)return c._documentBuyer;const cu=customer(c.customerId)||{};return{name:cu.name||'',address:cu.address||'',country:cu.country||''}}
function documentContext(c,seller,buyer=null){return{...c,seller,_documentBuyer:buyer||buyerOf(c)}}
function pakistanExporterKey(s){return s?.customs?.exporter==='BRM'?'BRM':'TTI'}
function pakistanCustomsContext(s,c){const tg=SELLER_DETAILS.TG,context=documentContext(c,pakistanExporterKey(s),{name:tg.name,address:tg.address,country:'United Arab Emirates'});context.currency=s.seller==='TG'?(s.customs?.currency||c.currency):c.currency;return context}
function customsPartyOptions(s,c){const cu=customer(c.customerId)||{},rows=[];if(s.seller==='TG')rows.push({value:'TG',label:'TG',party:{name:SELLER_DETAILS.TG.name,address:SELLER_DETAILS.TG.address,country:'United Arab Emirates'}});rows.push({value:'BUYER',label:'Actual Buyer',party:buyerOf(c)});(cu.notifies||[]).forEach((n,i)=>rows.push({value:`NOTIFY:${i}`,label:n.name||`Notify Party ${i+1}`,party:{name:n.name||'',address:n.address||'',country:n.country||''}}));return rows}
function customsDocumentContext(s,c){const options=customsPartyOptions(s,c),choice=s.customs?.importerChoice||(s.seller==='TG'?'TG':'BUYER'),selected=options.find(x=>x.value===choice)||options[0]||{party:buyerOf(c)},seller=s.seller==='TG'?pakistanExporterKey(s):c.seller,context=documentContext(c,seller,selected.party);return{...context,currency:s.seller==='TG'?(s.customs?.currency||c.currency):c.currency,paymentCode:s.seller==='TG'?'INTERCOMPANY':c.paymentCode,_customsPartyHeading:true}}
function pakistanOriginContext(s,c){return documentContext(c,pakistanExporterKey(s),buyerOf(c))}
function letterhead(c){const x=sellerOf(c),key=String(c?.seller||'TTI').toUpperCase();return x.header?`<div class="docLetterhead seller${esc(key)}"><img src="${x.header}" alt="${esc(x.name)}"></div>`:`<div class="docLetterheadText"><b>${esc(x.name)}</b><span>${esc(x.address)}</span><span>${esc([x.phone,x.email,x.website].filter(Boolean).join(' · '))}</span></div>`}
function footerArt(c){const x=sellerOf(c);return x.footer?`<div class="docFooterArt"><img src="${x.footer}" alt=""></div>`:''}
function signature(c){const x=sellerOf(c);return`<div class="docAutoSign">For <b>${esc(x.name)}</b>${x.sign?`<img src="${x.sign}" alt="Authorised signature">`:''}<div>Authorised Signatory</div></div>`}
function conditionalOutputSignature(c){return signature(c).replace('class="docAutoSign"','class="docAutoSign conditionalOutputSignature"')}
function partyGrid__legacy_v0(c){const s=sellerOf(c),b=buyerOf(c);return`<div class="docPartyGrid"><div><div class="docPartyLabel">SELLER / EXPORTER</div><div class="docPartyName">${esc(s.name)}</div><div>${esc(s.address)}</div></div><div><div class="docPartyLabel">${c._customsPartyHeading?'BY ORDER AND FOR ACCOUNT OF':'BUYER / IMPORTER'}</div><div class="docPartyName">${esc(b.name)}</div><div>${esc(b.address)}</div></div></div>`}
function pageDoc(c,title,body){return`<div class="printDoc"><section class="docPage branded">${letterhead(c)}<h1 class="docTitle">${esc(title)}</h1>${body}${footerArt(c)}<div class="docPageNo">Generated ${fmt(TODAY())}</div></section></div>`}
function packingPrefix(i,total){return total>1?`${String.fromCharCode(65+i)}. `:''}
function packingDescription(p,c,i,total){return`${packingPrefix(i,total)}${num(p.size)} ${esc(c.packingUnit)} ${esc(p.type)}${p.brand?` — Brand: ${esc(p.brand)}`:''}${p.masterBag?.enabled?` in master bags (${num(p.masterBag.qty).toLocaleString()} pcs, tare ${num(p.masterBag.tare)}g)`:''}`}
function customsPlannedRows(s,c){const source=s.kind==='lot'&&s.loadingPlan?.allocations?.length?s.loadingPlan.allocations:(c.packings?.length?c.packings:[{containers:c.containers,weightPer:c.weightPer}]).map((p,i)=>({packIndex:i,containers:p.containers||c.containers,weightPer:p.weightPer||c.weightPer})),groups=new Map();for(const a of source){const packIndex=num(a.packIndex),p=c.packings?.[packIndex]||c.packings?.[0]||{},key=String(packIndex),g=groups.get(key)||{packIndex,p,shares:0,netKg:0};g.shares+=num(a.containers);g.netKg+=num(a.containers)*num(a.weightPer)*1000;groups.set(key,g)}return[...groups.values()].map((g,i)=>{const p=g.p,unitKg=String(c.packingUnit||'KG').toUpperCase().startsWith('LB')?num(p.size)*.45359237:num(p.size),bags=unitKg?Math.round(g.netKg/unitKg):0,masterTare=p.masterBag?.enabled?num(p.masterBag.qty)*num(p.masterBag.tare)/1000:0,tareKg=bags*num(p.tare)/1000+masterTare;return{number:'',seal:'',bags,netKg:g.netKg,tareKg,grossKg:g.netKg+tareKg,brand:p.brand||'',packing:`${num(p.size)} ${c.packingUnit||'KG'} ${p.type||''}`,location:'',loadedDate:'',_planned:true,index:i+1,packIndex:g.packIndex,containerShares:g.shares}})}
function totalsFor(rows){const net=rows.reduce((a,x)=>a+num(x.netKg),0),bags=rows.reduce((a,x)=>a+num(x.bags),0),tare=rows.reduce((a,x)=>a+num(x.tareKg),0);return{rows,net,bags,tare,gross:net+tare,mt:net/1000}}
function plannedTotals(s,c){return totalsFor(customsPlannedRows(s,c))}
function plannedPhysicalRows(s,c){const t=plannedTotals(s,c),count=Math.max(1,Math.round(num(s.containers)||t.rows.reduce((a,x)=>a+num(x.containerShares),0))),sample=t.rows[0]||{};return Array.from({length:count},(_,i)=>{const netKg=t.net/count,bags=Math.round(t.bags/count),tareKg=t.tare/count;return{number:'',seal:'',bags,netKg,tareKg,grossKg:netKg+tareKg,brand:sample.brand||'',packing:sample.packing||'',location:'',loadedDate:'',_planned:true,index:i+1}})}
function actualRows(s,c){return Array.isArray(s.millActuals)&&s.millActuals.length?s.millActuals:plannedPhysicalRows(s,c)}
function actualTotals(s,c){return totalsFor(actualRows(s,c))}
function normalizeContainerNumber(value){return String(value||'').replace(/[^A-Za-z0-9]/g,'').toUpperCase()}
function formatContainerNumber(value){const clean=normalizeContainerNumber(value);return CONTAINER_RE.test(clean)?`${clean.slice(0,10)}-${clean.slice(10)}`:String(value||'').trim().toUpperCase()}
function millActualsComplete(s){const expected=num(s?.containers),rows=Array.isArray(s?.millActuals)?s.millActuals:[],numbers=rows.map(x=>normalizeContainerNumber(x.number));return expected>0&&rows.length===expected&&numbers.every(x=>CONTAINER_RE.test(x))&&new Set(numbers).size===expected&&rows.every(x=>String(x.seal||'').trim())}
function salesContractPrintLegacy(c){const b=buyerOf(c),total=c.packings.length,specs=contractSpecRows(c),terms=effectiveTerms(c),quality=c.quality||qualityDescription(c),additional=c.additionalQuality||DEFAULT_QUALITY,ref=`<div class="docRefGrid"><div class="docRefBox"><b>Contract Reference</b>${esc(c.ref)}</div><div class="docRefBox"><b>Buyer</b>${esc(b.name)}</div></div>`,page1=`<div class="docRefGrid"><div class="docRefBox"><b>Contract Reference</b>${esc(c.ref)}</div><div class="docRefBox"><b>Date</b>${fmt(c.date)}</div></div>${partyGrid(c)}<h3 class="docSection">QUALITY</h3><p><b>${esc(quality)}</b></p><h3 class="docSection">SPECIFICATIONS</h3>${specs.length?`<table class="docTable"><thead><tr><th>S/No.</th><th>Specification</th><th>Value</th></tr></thead><tbody>${specs.map((x,i)=>`<tr><td>${i+1}</td><th>${esc(x.name)}</th><td>${esc(x.value)}</td></tr>`).join('')}</tbody></table>`:''}<p>${esc(additional)}</p><h3 class="docSection">QUANTITY & SHIPMENT</h3><p><b>${num(c.qty).toFixed(3)} MTONS ±${num(c.tolerance)}%</b> · Latest shipment ${fmt(c.shipmentDate)||'TO BE ADVISED'}<br>From ${esc(c.pol)} to ${esc(c.podPort||c.destPort)}</p><h3 class="docSection">PACKING & PRICE</h3>${c.packings.map((p,i)=>{const pc=priceComponents(p,c);return`<p>${packingDescription(p,c,i,total)} · ${num(p.containers)} container(s) × ${num(p.weightPer).toFixed(3)} MT · Tare ${num(p.tare)}g · <b>${esc(c.currency)} ${pc.finalRate.toFixed(2)}/MT ${esc(c.incoterm)}</b>${c.showAllPrices?`<br>CNF/CFR ${esc(c.currency)} ${pc.finalRate.toFixed(2)} · Freight ${esc(c.currency)} ${pc.freight.toFixed(2)}${c.incoterm==='CIF'?` · Insurance ${esc(c.currency)} ${pc.insurance.toFixed(2)}`:''} · FOB ${esc(c.currency)} ${pc.fob.toFixed(2)}`:''}</p>`}).join('')}<h3 class="docSection">PAYMENT</h3><p>${esc(paymentText(c))}</p>`,page2=`${ref}${terms.length?`<h3 class="docSection">OTHER TERMS</h3><ol>${terms.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}`,page3=`${ref}${documentsPresented(c).length?`<h3 class="docSection">DOCUMENTS TO BE PRESENTED</h3><table class="docTable"><thead><tr><th>Sequence</th><th>Document Name</th><th>Original</th><th>Copies</th></tr></thead><tbody>${documentsPresented(c).map(r=>`<tr><td>${r.sequence}</td><td>${esc(r.name)}</td><td>${r.original}</td><td>${r.copies}</td></tr>`).join('')}</tbody></table>`:''}<h3 class="docSection">VALIDITY</h3><p>Signed/stamped copy latest <b>${fmt(c.signedDeadline)}</b>; ${c.paymentCode.startsWith('LC_')?'L/C':'payment'} latest <b>${fmt(c.paymentDeadline)}</b>. THEREAFTER SUBJECT TO OUR RE-CONFIRMATION.</p><div class="docSignatures">${signature(c)}<div class="docSig"><div class="docSignatureSpace"></div>For <b>${esc(b.name)}</b><br>Authorised Signatory</div></div>`;return pageDoc(c,'SALES CONTRACT',page1)+pageDoc(c,'SALES CONTRACT — TERMS',page2)+pageDoc(c,'SALES CONTRACT — DOCUMENTS & ACCEPTANCE',page3)}
function lcApplies(s,c){return String(c?.paymentCode||'').startsWith('LC_')&&!!s?.lc?.saved}
