function lcDraftDoc(s,c){const l=s.lc||{},amount=invoiceLines(s,c,false).reduce((sum,line)=>sum+num(line.amount),0);return pageDoc(c,'BILL OF EXCHANGE',`<div class="draftCopyLabel">ORIGINAL / DUPLICATE</div><div class="draftAmount">${esc(c.currency)} ${amount.toLocaleString(undefined,{minimumFractionDigits:2})}</div><div class="draftBody"><p>At <span class="draftLine">${c.paymentCode==='LC_USANCE'?`${num(c.usanceDays||l.usanceDays)} days from B/L date`:'SIGHT'}</span> pay to the order of <span class="draftLine">${esc(l.advisingBank||s.covering.bank||'SELLER’S BANK')}</span> the sum of ${esc(c.currency)} ${amount.toLocaleString(undefined,{minimumFractionDigits:2})}.</p><p>Drawn under L/C No. <b>${esc(l.lcNo)}</b> dated ${fmt(l.lcDate)} issued by ${esc(l.issuingBank)}.</p><p>TO: ${esc(l.issuingBank)}</p></div>${signature(c)}`)}
