function documentSpecificationHTML(s,c){if(s?.bl?.includeSpecification===false)return'';if(!buyerSpecificationSelected(c))return'';const rows=contractSpecRows(c);return rows.length?`<br>${rows.map(row=>`${esc(String(row.name||'').toUpperCase())}: ${esc(String(row.value||'').toUpperCase())}`).join('<br>')}`:''}
function bagMarkingCell(s,brand){const label=outputBrand(brand),art=bagArtworkFor(s,brand);return`<div class="docBrand"><b>${esc(label)}</b>${art?`<img src="${esc(art)}" alt="${esc(label)} bag marking">`:''}</div>`}
function numberWordsBelowThousand(n){const ones=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'],tens=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];if(n<20)return ones[n];if(n<100)return tens[Math.floor(n/10)]+(n%10?'-'+ones[n%10]:'');return ones[Math.floor(n/100)]+' hundred'+(n%100?' '+numberWordsBelowThousand(n%100):'')}
function amountInWords(value,currency){let n=Math.max(0,Math.floor(num(value))),parts=[];for(const [size,name] of [[1000000000,'billion'],[1000000,'million'],[1000,'thousand']])if(n>=size){parts.push(numberWordsBelowThousand(Math.floor(n/size))+' '+name);n%=size}if(n||!parts.length)parts.push(numberWordsBelowThousand(n));const cents=Math.round((num(value)-Math.floor(num(value)))*100);return`${String(currency||'').toUpperCase()} ${parts.join(' ')}${cents?` and ${cents}/100`:''} only`.toUpperCase()}
function loadingProgrammeFor(s){return s.loadingProgrammeNo||s.loadingPlan?.loadingProgrammeNo||''}
