// Restore the original Lot icon screen. Document work opens in one temporary
// two-column editor above the icons and returns to the Lot after a valid save.
const LOT_EDITOR_TITLES={customs:'Customs Documents',bl:'B/L Draft',commercial:'Commercial Invoice & Packing List',coo:'Certificate of Origin',certs:'+ Certificate',uploads:'Upload Documents',cover:'Bank & Dispatch',tg:'TG Documents',lcdraft:'L/C Draft',output:'Final Output',history:'History'};
const LOT_EDITOR_SAVE_CONTROLS={customs:'#saveCustoms',bl:'#saveBL',commercial:'#saveCommercial',coo:'#saveCOO',certs:'#saveGeneratedCertificate',uploads:'#saveLotDocument',cover:'#saveCover',tg:'#printTGPakistan'};

function closeLotEditor(){activeWorkspace='';renderShipmentWorkspace()}
function wireLotEditorSave(form,key){const selector=LOT_EDITOR_SAVE_CONTROLS[key];if(!selector)return;const button=form.querySelector(selector);if(!button||button.dataset.returnToLot)return;button.dataset.returnToLot='1';const original=button.onclick;if(!original)return;button.onclick=event=>{const before=(state.audits||[]).length,result=original.call(button,event),finish=()=>{if((state.audits||[]).length>before&&activeWorkspace===key)closeLotEditor()};if(result&&typeof result.then==='function')return result.then(value=>{finish();return value});finish();return result}}

function splitLotDocumentWorkspace(d,key,title){const s=shipment(),c=contractByRef(s.contractRef),children=[...d.childNodes];d.innerHTML='<div class="lotSplitWorkspace"><div class="lotFormPane"></div><aside class="lotPreviewPane"><div class="lotPreviewHead"><b>'+esc(title)+'</b><span>Document preview</span></div><div class="lotPreviewPaper"></div></aside></div>';const form=d.querySelector('.lotFormPane'),paper=d.querySelector('.lotPreviewPaper');children.forEach(node=>form.appendChild(node));const update=()=>{try{paper.innerHTML=liveLotDocument(key,s,c)||'<div class="previewEmpty">The document preview will appear here when its information is available.</div>'}catch(error){paper.innerHTML='<div class="previewEmpty">Complete the requested information to preview this document.</div>'}};form.querySelectorAll('input,select,textarea').forEach(control=>{control.addEventListener('input',update);control.addEventListener('change',update)});wireLotEditorSave(form,key);update()};

function splitSupportingLotWorkspace(d,key){if(d.querySelector('.lotSplitWorkspace'))return;const children=[...d.childNodes];d.innerHTML='<div class="lotSplitWorkspace"><div class="lotFormPane"></div><aside class="lotPreviewPane"><div class="lotPreviewHead"><b>'+esc(LOT_EDITOR_TITLES[key]||'Document')+'</b><span>Document information</span></div><div class="previewEmpty">Saved documents and output remain attached to this Lot.</div></aside></div>';const form=d.querySelector('.lotFormPane');children.forEach(node=>form.appendChild(node));wireLotEditorSave(form,key)}

