function uxSettings(){state.settings=state.settings||{};for(const key of ['customPackingTypes','customCurrencies','customInspections'])state.settings[key]=Array.isArray(state.settings[key])?state.settings[key]:[];state.deletedShipments=Array.isArray(state.deletedShipments)?state.deletedShipments:[];return state.settings}
function uniqueValues(fixed,custom){return[...new Set([...fixed,...(custom||[])].map(v=>String(v||'').trim()).filter(Boolean))]}
function selectOptions(values,current,customLabel='+ Custom'){const known=values.includes(current);return`<option value="">Select</option>${values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}<option value="__custom__" ${current&&!known?'selected':''}>${customLabel}</option>`}
function normalizedPartyName(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b(?:private|pvt|limited|ltd|llc|l\.l\.c|incorporated|inc|company|co)\b/g,'').replace(/[^a-z0-9]/g,'')}
function closeNameMatch(value){const key=normalizedPartyName(value);return state.customers.find(c=>normalizedPartyName(c.name)===key)}
function nameDistance(a,b){const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old}}return row[b.length]}
function similarNameMatch(value){const key=normalizedPartyName(value);if(key.length<5)return null;return state.customers.find(c=>{const other=normalizedPartyName(c.name);if(other===key)return false;if(key.includes(other)||other.includes(key))return Math.min(key.length,other.length)>=5;return 1-nameDistance(key,other)/Math.max(key.length,other.length)>=.86})}
function nextLotReference(process){const used=lotsFor(process).map(l=>{const m=String(l.lotId||'').match(/\/L(\d+)$/i);return m?num(m[1]):0});return`${process.contractRef}/L${String((used.length?Math.max(...used):0)+1).padStart(2,'0')}`}
