function validateContractStep(n){const c=contractDraft;if(n===1&&!c.customerId)return'Add or select a Customer.';if(n===1&&!String(c.ref||'').trim())return'Contract Reference required.';if(n===2&&productMasters().length&&!c.productIdentityCode)return'Select a Product / Variety from Products & Quality Master.';if(n===2&&!String(c.product||'').trim())return'Select a Product / Variety.';if(n===2&&!brokenEntryValid(c.brokenText))return'Enter Broken as a percentage, for example 5 or 15-20. The % sign is added automatically.';if(n===2&&!String(c.finish||'').trim())return'Select the Finish for this Sales Contract.';if(n===2&&!String(c.cropYear||'').match(/^\d{4}\/\d{4}$/))return'Set the Current Crop Year in Products & Quality Master.';if(n===2&&buyerSpecificationSelected(c)&&!contractSpecRows(c).length)return'Enter at least one Buyer Specification.';if(n===3&&(num(c.containers)<=0||num(c.weightPer)<=0))return'Enter containers and weight per container.';if(n===4&&!c.packings.length)return'Add at least one packing.';if(n===4){const containers=c.packings.reduce((sum,row)=>sum+num(row.containers),0);if(Math.abs(containers-num(c.containers))>.001)return'Containers assigned across the packing tabs must equal the total containers in Quantity & Shipment.';c.packings.forEach(row=>row.weightPer=num(c.weightPer))}if(n===5&&c.packings.some(row=>unitRate(row,c)<=0))return'Enter PRICE / MT for every packing.';if(n===6&&c.paymentCode==='CUSTOM'&&!String(c.customPayment||'').trim())return'Enter Custom Payment Terms.';if(n===6&&paymentNeedsSellerBank(c)&&!selectedContractBank(c))return'Select the Seller bank account for the advance payment.';if(n===7&&(!c.signedDeadline||!c.paymentDeadline))return'Enter the signed-contract and payment / L/C deadlines.';return''}
