  masterRows.push(`<tr class="masterBagOrderRow"><td>${serial++}</td><td><b>MASTER BAG${master.printed&&line.brand?` — ${esc(ttOutputEnglish(line.brand))}`:''}</b><br>${num(master.bagsPerMaster)} smaller bags in one master bag</td><td>${marking}</td><td>${num(master.tare)} g</td><td>${num(master.bagsPerMaster)*num(line.size)} ${esc(String(line.unit||'KG').toUpperCase())}</td><td><b>${quantity.toLocaleString()}</b></td></tr>`)
